-- Tabela de referência geográfica de municípios brasileiros
-- Fonte: IBGE via kelvins/municipios-brasileiros (GitHub)
-- Nomes armazenados SEM acento, UPPERCASE
-- Usada por gold_mv_comparativo_anp para fallback de proximidade (Haversine)
CREATE TABLE IF NOT EXISTS torre.ref_municipios_brasil (
  codigo_ibge  CHAR(7)        NOT NULL PRIMARY KEY,
  municipio    TEXT           NOT NULL,
  uf           CHAR(2)        NOT NULL,
  latitude     NUMERIC(10,6)  NOT NULL,
  longitude    NUMERIC(10,6)  NOT NULL,
  capital      BOOLEAN        NOT NULL DEFAULT FALSE
);

CREATE INDEX IF NOT EXISTS idx_ref_mun_uf
  ON torre.ref_municipios_brasil (uf);
CREATE INDEX IF NOT EXISTS idx_ref_mun_nome
  ON torre.ref_municipios_brasil (municipio);
CREATE INDEX IF NOT EXISTS idx_ref_mun_uf_nome
  ON torre.ref_municipios_brasil (uf, municipio);

SELECT 'Tabela pronta' AS status;

parameters.jsCode:
// Parseia o CSV de municípios brasileiros e constrói o INSERT SQL
// Fonte: kelvins/municipios-brasileiros (IBGE)
// Colunas esperadas: codigo_ibge, nome, latitude, longitude, capital, codigo_uf
const raw = $input.first().json.data || $input.first().json.body || '';
if (!raw) throw new Error('CSV vazio. Verifique a URL ou o formato de resposta do HTTP Request.');

const csvText = raw.replace(/\r/g, '');
const lines = csvText.trim().split('\n');
const headers = lines[0].split(',').map(h => h.trim().replace(/"/g, ''));

const iCodigo  = headers.indexOf('codigo_ibge');
const iNome    = headers.indexOf('nome');
const iLat     = headers.indexOf('latitude');
const iLon     = headers.indexOf('longitude');
const iCapital = headers.indexOf('capital');
const iUfSigla = headers.indexOf('uf');
const iUfCode  = headers.indexOf('codigo_uf');

if (iCodigo < 0 || iNome < 0 || iLat < 0 || iLon < 0) {
  throw new Error('Colunas nao encontradas. Headers detectados: ' + headers.join(', '));
}

const ufMap = {
  '11':'RO','12':'AC','13':'AM','14':'RR','15':'PA',
  '16':'AP','17':'TO','21':'MA','22':'PI','23':'CE',
  '24':'RN','25':'PB','26':'PE','27':'AL','28':'SE',
  '29':'BA','31':'MG','32':'ES','33':'RJ','35':'SP',
  '41':'PR','42':'SC','43':'RS','50':'MS','51':'MT',
  '52':'GO','53':'DF'
};

function parseLine(line) {
  const result = [];
  let field = '';
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') { inQuotes = !inQuotes; }
    else if (ch === ',' && !inQuotes) { result.push(field); field = ''; }
    else { field += ch; }
  }
  result.push(field);
  return result;
}

function stripAccents(str) {
  return str.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

const values = [];
const skipped = [];
for (let i = 1; i < lines.length; i++) {
  const cols = parseLine(lines[i].trim());
  if (cols.length < 5) continue;

  const codigo  = cols[iCodigo].trim();
  const nome    = stripAccents(cols[iNome].trim()).toUpperCase().replace(/'/g, "''");
  const lat     = parseFloat(cols[iLat]);
  const lon     = parseFloat(cols[iLon]);
  const capital = cols[iCapital] && cols[iCapital].trim() === '1';

  let uf = '';
  if (iUfSigla >= 0 && cols[iUfSigla] && cols[iUfSigla].trim().length === 2) {
    uf = cols[iUfSigla].trim().toUpperCase();
  } else if (iUfCode >= 0) {
    uf = ufMap[cols[iUfCode].trim()] || '';
  }

  if (!codigo || !nome || isNaN(lat) || isNaN(lon) || !uf) {
    skipped.push(lines[i].substring(0, 60));
    continue;
  }

  values.push("('" + codigo + "','" + nome + "','" + uf + "'," + lat + "," + lon + "," + capital + ")");
}

if (values.length === 0) {
  throw new Error('Nenhum municipio parseado. Verifique o formato do CSV. Linhas ignoradas: ' + skipped.slice(0, 3).join(' | '));
}

const sql =
  "INSERT INTO torre.ref_municipios_brasil (codigo_ibge, municipio, uf, latitude, longitude, capital)\n" +
  "VALUES\n" +
  values.join(',\n') +
  "\nON CONFLICT (codigo_ibge) DO UPDATE SET" +
  "\n  municipio = EXCLUDED.municipio," +
  "\n  uf        = EXCLUDED.uf," +
  "\n  latitude  = EXCLUDED.latitude," +
  "\n  longitude = EXCLUDED.longitude," +
  "\n  capital   = EXCLUDED.capital;";

return [{ json: { query: sql, total_municipios: values.length, linhas_ignoradas: skipped.length } }];
